#!/bin/bash
set -e

# ==============================================================
# kaviancrypto v7.0 Pro Terminal - Complete All-in-One Installer
# Clean Overview Hierarchy:
#   1) Full-Width Live Server Telemetry (CPU / RAM / Disk)
#   2) 4-Box KPI Row (Last Scan / Schedules / 24H / 7D Performance)
#   3) Full-Width Latest Detected Signals
#   4) Full-Width Tracked Signals (Live TP/SL Progress)
# + Dedicated Full-Screen Live Console Tab (Search + Filter + Copy)
# + 4 Live Architectural Themes (Obsidian / Linear / TV Pro / Bento HUD)
# + Global Position Direction Mode (Smart Auto / LONG Only / SHORT Only)
# + Dedicated Backup Bot Token + kaviancrypto v4.2 Default Strategy
# Fresh Install + Safe Repair/Upgrade (Preserves config.json,
# active_trades.json, sent_signals.json & custom_strategy.py)
# ==============================================================

APP_DIR="/opt/kaviancrypto"
PORT="8888"

echo "========================================================"
echo "  kaviancrypto v7.0 Pro - All-in-One Installer & Upgrade"
echo "  Clean Overview + Dedicated Console + 4 Themes + v4.2"
echo "========================================================"

echo "=== [1/6] Stopping existing service (if running) & preparing $APP_DIR ==="
systemctl stop kaviancrypto.service 2>/dev/null || true
mkdir -p "$APP_DIR"
cd "$APP_DIR"

SCRIPT_SRC="$(readlink -f "$0" 2>/dev/null || echo "$0")"
if [ -f "$SCRIPT_SRC" ] && [ "$SCRIPT_SRC" != "$APP_DIR/install_kaviancrypto_v7_0.sh" ]; then
    cp -f "$SCRIPT_SRC" "$APP_DIR/install_kaviancrypto_v7_0.sh" 2>/dev/null || true
    chmod +x "$APP_DIR/install_kaviancrypto_v7_0.sh" 2>/dev/null || true
fi

echo "=== [2/6] Installing system prerequisites ==="
apt-get update -y
apt-get install -y python3 python3-venv python3-pip curl

